.password-input-wrap {
  position: relative;
  display: block;
}

.password-input-wrap .input {
  padding-inline-end: 3.15rem;
}

/* Keep one consistent Renvix visibility control. Chromium/Edge otherwise
   adds a second native reveal icon on password fields. */
input[type="password"]::-ms-reveal,
input[type="password"]::-ms-clear,
input[type="password"]::-webkit-credentials-auto-fill-button,
input[type="password"]::-webkit-textfield-decoration-container {
  display: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.password-toggle {
  position: absolute;
  inset-inline-end: .65rem;
  top: 50%;
  width: 2rem;
  height: 2rem;
  padding: 0;
  display: grid;
  place-items: center;
  transform: translateY(-50%);
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #64748b;
  cursor: pointer;
  transition: background .18s ease, color .18s ease;
}

.password-toggle:hover,
.password-toggle:focus-visible {
  background: #F3F8F7;
  color: #0B3F3B;
  outline: none;
}

.password-toggle .line-icon {
  width: 1.1rem;
  height: 1.1rem;
}

.notification-trigger-wrap {
  position: relative;
  z-index: 125;
}

.notification-trigger {
  position: relative;
}

.notification-badge {
  position: absolute;
  inset-inline-end: -2px;
  top: -3px;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  display: grid;
  place-items: center;
  border: 2px solid var(--surface, #fff);
  border-radius: 999px;
  background: #ef4444;
  color: #fff;
  font-size: 9px;
  font-weight: 800;
  line-height: 1;
}

.notification-dropdown {
  position: absolute;
  top: calc(100% + 12px);
  inset-inline-end: 0;
  z-index: 120;
  width: min(390px, calc(100vw - 32px));
  max-height: calc(100dvh - 92px);
  margin: 0;
  overflow: hidden;
  border: 1px solid #E8F1F0;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 16px 38px rgba(6, 43, 40, .15);
}

.notification-dropdown-head,
.notification-dropdown-actions {
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.notification-dropdown-head {
  border-bottom: 1px solid #F3F8F7;
  font-size: 12px;
}

.notification-dropdown-list {
  max-height: min(350px, calc(100dvh - 178px));
  padding: 8px;
  display: grid;
  gap: 7px;
  overflow: auto;
  overscroll-behavior: contain;
  background: #F3F8F7;
}

.notification-item {
  --notification-tone: #0B3F3B;
  --notification-soft: #F3F8F7;
  position: relative;
  width: 100%;
  min-height: 66px;
  border: 1px solid color-mix(in srgb, var(--notification-tone) 17%, #E8F1F0);
  border-radius: 10px;
  background: color-mix(in srgb, var(--notification-soft) 44%, #fff);
  color: #062B28;
  overflow: hidden;
}

.notification-item-success {
  --notification-tone: #14a66f;
  --notification-soft: #ecfdf5;
}

.notification-item-danger {
  --notification-tone: #ef4444;
  --notification-soft: #fff1f2;
}

.notification-item-warning {
  --notification-tone: #f59e0b;
  --notification-soft: #fff7ed;
}

.notification-item-open {
  width: 100%;
  min-height: 64px;
  padding: 9px 36px 9px 9px;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  text-align: start;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.notification-item:hover,
.notification-item.unread {
  background: color-mix(in srgb, var(--notification-soft) 72%, #fff);
}

.notification-item-icon {
  width: 29px;
  height: 29px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: color-mix(in srgb, var(--notification-tone) 11%, #fff);
  color: var(--notification-tone);
}

.notification-item-icon .line-icon {
  width: 15px;
  height: 15px;
}

.notification-item-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.notification-item-dismiss {
  position: absolute;
  inset-inline-end: 7px;
  top: 7px;
  width: 22px;
  height: 22px;
  padding: 0;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #7a8799;
  cursor: pointer;
}

.notification-item-dismiss:hover,
.notification-item-dismiss:focus-visible {
  background: rgba(255, 255, 255, .75);
  color: var(--notification-tone);
  outline: none;
}

.notification-item-dismiss .line-icon {
  width: 12px;
  height: 12px;
}

.notification-item strong,
.notification-item small,
.notification-item em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.notification-item small,
.notification-item em {
  color: #71819a;
  font-size: 9.5px;
}

.notification-item strong {
  color: var(--notification-tone);
  font-size: 11px;
  line-height: 1.45;
}

.notification-item em {
  font-style: normal;
  font-size: 9px;
}

.notification-empty {
  padding: 28px 18px;
  display: grid;
  gap: 6px;
  text-align: center;
  color: #71819a;
  font-size: 12px;
}

.notification-list-page {
  display: grid;
  gap: 10px;
}

.notification-row {
  padding: 14px;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  border: 1px solid #F3F8F7;
  border-radius: 14px;
  background: #fff;
}

.notification-row.unread {
  border-color: #E8F1F0;
  background: #F3F8F7;
}

.notification-row-content {
  min-width: 0;
}

.notification-row-title {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.notification-row-content p {
  margin: 5px 0;
  color: #0B3F3B;
}

.notification-row-content small {
  color: #8290a5;
  font-size: 11px;
}

.compact-field {
  min-width: 140px;
}

.compact-field > span {
  font-size: 11px;
}

:root[data-theme="dark"] .password-toggle:hover,
:root[data-theme="dark"] .password-toggle:focus-visible {
  background: #062B28;
