/* Google Identity Services and remembered-device account selector. */
.auth-known-account{display:grid;gap:9px;margin:2px 0 12px}
.auth-known-account-card,.auth-known-account-another{
  width:100%;min-height:64px;padding:10px 14px;display:flex;align-items:center;gap:12px;
  color:#153b38;border:1px solid #dce9e7;border-radius:12px;background:#fff;cursor:pointer;
  transition:border-color .18s ease,box-shadow .18s ease,transform .18s ease
}
.auth-known-account-card:hover,.auth-known-account-another:hover{border-color:#77bcb4;box-shadow:0 8px 22px rgba(6,43,40,.08);transform:translateY(-1px)}
.auth-known-account-avatar{width:46px;height:46px;display:grid;place-items:center;overflow:hidden;flex:0 0 auto;color:#08786e;border-radius:50%;background:#e6f5f2;font-size:18px;font-weight:800}
.auth-known-account-avatar img{width:100%;height:100%;display:block;object-fit:cover}
.auth-known-account-copy{min-width:0;display:grid;gap:2px;text-align:start}
.auth-known-account-copy strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px}
.auth-known-account-copy small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#758682;font-size:12px;direction:ltr;text-align:start}
.auth-known-account-check{width:23px;height:23px;margin-inline-start:auto;display:grid;place-items:center;color:#fff;border-radius:50%;background:#0b7d73;font-size:13px}
.auth-known-account-another{min-height:48px;justify-content:center;border-style:dashed;color:#38635f;background:transparent;font-size:13px}
.auth-known-account-another>span{width:27px;height:27px;display:grid;place-items:center;border:1px solid currentColor;border-radius:50%;font-size:19px;line-height:1}
.auth-google-area{display:grid;gap:8px;margin-top:1px;transition:opacity .18s ease}.auth-google-area.is-busy{opacity:.65;pointer-events:none}
.auth-google-divider{display:flex;align-items:center;gap:10px;color:#7d8b89;font-size:12px;text-align:center}
.auth-google-divider::before,.auth-google-divider::after{content:"";height:1px;flex:1;background:#e2ecea}.auth-google-divider span{white-space:nowrap}
.auth-google-button{width:100%;min-height:44px;display:flex;align-items:center;justify-content:center;overflow:hidden;border-radius:8px}
.auth-google-button>div,.auth-google-button iframe{max-width:100%!important}
.auth-google-placeholder{width:100%;min-height:42px;display:flex;align-items:center;justify-content:center;gap:11px;color:#3c4043;border:1px solid #aeb9b7;border-radius:7px;background:#fff;font:600 13px/1.2 Tajawal,Arial,sans-serif;opacity:1}
.auth-google-placeholder svg{width:18px;height:18px;flex:0 0 auto}
.auth-google-status{margin:0;color:#b44343;font-size:11.5px;line-height:1.6;text-align:center}.auth-google-status[data-tone="info"]{color:#377a74}
.auth-google-server-fallback{justify-self:center;border:0;background:none;color:#087f70;font:600 11.5px/1.5 Tajawal,Arial,sans-serif;text-decoration:underline;cursor:pointer}.auth-google-server-fallback:disabled{opacity:.55;cursor:wait}
.auth-google-legal{margin:0;color:#7c8d8a;font-size:10.5px;line-height:1.6;text-align:center}

.auth-suite-page[data-auth-theme="dark"] .auth-known-account-card,
.auth-suite-page[data-auth-theme="dark"] .auth-known-account-another{color:#dce9e7;border-color:#244643;background:#102826}
.auth-suite-page[data-auth-theme="dark"] .auth-known-account-another{background:transparent}
.auth-suite-page[data-auth-theme="dark"] .auth-google-placeholder{color:#e6efed;border-color:#49635f;background:#101918}
.auth-suite-page[data-auth-theme="dark"] .auth-google-server-fallback{color:#61d5c4}
.auth-suite-page[data-auth-theme="dark"] .auth-known-account-copy small,
.auth-suite-page[data-auth-theme="dark"] .auth-google-divider,
.auth-suite-page[data-auth-theme="dark"] .auth-google-legal{color:#9db1ae}
.auth-suite-page[data-auth-theme="dark"] .auth-google-divider::before,
.auth-suite-page[data-auth-theme="dark"] .auth-google-divider::after{background:#294744}

@media (max-width:820px){
  .auth-suite-page .auth-suite-brandbar-controls{direction:ltr!important}
}
@media (max-width:600px){
  .auth-known-account{margin-bottom:9px}.auth-known-account-card{min-height:58px;padding:8px 11px}.auth-known-account-avatar{width:40px;height:40px}
  .auth-known-account-another{min-height:43px}.auth-google-area{gap:6px}.auth-google-legal{font-size:9.5px}
