  filter:none;
  animation:homeStepConnectorFlow 7s linear calc(var(--connector-index) * -.9s) infinite;
}
.marketing-home-v3 .marketing-step-connector-dot{
  fill:#078f82;
  stroke:#eafffb;
  stroke-width:2;
  filter:none;
}
.marketing-home-v3 .marketing-step-connector-chevron{
  fill:#255f59;
  stroke:#fff;
  stroke-width:8px;
  paint-order:stroke fill;
  font:700 19px/1 Arial,sans-serif;
  letter-spacing:-3px;
  opacity:.9;
  transform-box:fill-box;
  transform-origin:center;
  animation:homeStepChevronNudge 2.1s ease-in-out calc(var(--connector-index) * -.25s) infinite;
}
.marketing-home-v3 .marketing-steps.is-running .marketing-step-connector-reveal{animation:homeStepConnectorReveal 1.15s var(--home-lower-ease) calc(var(--connector-index) * .16s + .18s) forwards}
.marketing-home-v3 .marketing-step.is-visible .marketing-step-card{animation:homeStepCardFloat 5.5s ease-in-out calc(var(--motion-index) * -.4s) infinite}
.marketing-home-v3 .marketing-step-number{
  position:relative;
  z-index:2;
  display:grid;
  width:100%;
  height:100%;
  place-items:center;
  border-radius:50%;
  animation:homeStepBadgePulse 3s ease-in-out calc(var(--motion-index) * -.4s) infinite;
}
.marketing-home-v3 .marketing-step-number-orbit{
  position:absolute;
  z-index:1;
  inset:-11px;
  border:1px dashed rgba(19,158,142,.38);
  border-right-color:transparent;
  border-bottom-color:rgba(19,158,142,.12);
  border-radius:50%;
  pointer-events:none;
  animation:homeStepBadgeOrbit 6s ease-in-out calc(var(--motion-index) * -.55s) infinite;
}
.marketing-home-v3 .marketing-step>b::before{
  position:absolute;
  inset:-5px;
  border:1px solid rgba(35,176,158,.16);
  border-radius:50%;
  content:"";
  animation:homeStepBadgeHalo 3.4s ease-in-out calc(var(--motion-index) * -.4s) infinite;
}
.marketing-home-v3 .marketing-step.is-visible .marketing-step-icon{animation:homeStepIconFloat 3.5s ease-in-out calc(var(--motion-index) * -.47s) infinite}
.marketing-home-v3 .marketing-step-ground{animation:homeStepGroundBreathe 4.2s ease-in-out calc(var(--motion-index) * -.4s) infinite}

/* Smart renewal journey: one route, one travelling light and route-synchronised nodes. */
.marketing-home-v3 .renewal-journey-path,
.marketing-home-v3 .renewal-journey-path-reveal,
.marketing-home-v3 .renewal-journey-path-flow{fill:none;vector-effect:non-scaling-stroke}
.marketing-home-v3 .renewal-journey-path{stroke:#addbd5;stroke-width:1.45}
.marketing-home-v3 .renewal-journey-path-reveal{stroke:#45b8aa;stroke-width:1.8;stroke-dasharray:1;stroke-dashoffset:1;opacity:.84}
.marketing-home-v3 .renewal-journey-path-flow{
  stroke:#087f74;
  stroke-width:2.35;
  stroke-linecap:round;
  stroke-dasharray:.08 .92;
  opacity:.54;
  filter:none;
  animation:homeJourneyPathFlow 10s linear 1.25s infinite;
}
.marketing-home-v3 .renewal-journey-glow-dot{
  fill:#0a8f82;
  stroke:#eafffb;
  stroke-width:2.5;
  filter:none;
}
.marketing-home-v3 .marketing-renewal-journey.is-in-view .renewal-journey-path-reveal{animation:homeJourneyPathReveal 1.2s var(--home-lower-ease) .18s forwards}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage .renewal-journey-marker{
  animation:homeJourneyNodePass 10s linear var(--journey-delay,1.25s) infinite;
  animation-play-state:running;
}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:first-of-type .renewal-journey-marker::before,
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:last-of-type .renewal-journey-marker::before{
  inset:-14px;
  border-style:dashed;
  border-color:rgba(17,156,140,.28) rgba(17,156,140,.08) rgba(17,156,140,.2) transparent;
  animation:homeJourneyEndpointOrbit 8s ease-in-out infinite;
}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:first-of-type .renewal-journey-marker,
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:last-of-type .renewal-journey-marker{
  border-color:#fff;
  outline:8px solid #fff;
  outline-offset:0;
  box-shadow:0 0 0 8px #fff,0 0 0 9px rgba(21,157,141,.15),0 12px 27px rgba(7,96,87,.16);
}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:first-of-type .renewal-journey-marker::after,
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:last-of-type .renewal-journey-marker::after{
  position:absolute;
  z-index:-1;
  inset:-8px;
  border-radius:50%;
  background:radial-gradient(circle,rgba(45,187,168,.16),rgba(45,187,168,.025) 63%,transparent 70%);
  content:"";
  animation:homeJourneyEndpointHalo 4.5s ease-in-out infinite;
}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:last-of-type .renewal-journey-marker::before,
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:last-of-type .renewal-journey-marker::after{animation-delay:-2.2s}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:nth-child(2) .renewal-journey-marker .line-icon{animation:homeJourneyCloudDrift 4.6s ease-in-out infinite}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:nth-child(4) .renewal-journey-marker .line-icon{animation:homeJourneySendDrift 5.2s var(--home-lower-ease) -.8s infinite}
.marketing-home-v3 .marketing-renewal-journey .renewal-journey-stage:nth-child(6) .renewal-journey-marker .line-icon{animation:homeJourneyStarGlow 4.8s ease-in-out -1.4s infinite}

@keyframes homeStepConnectorReveal{to{stroke-dashoffset:0}}
@keyframes homeStepConnectorFlow{from{stroke-dashoffset:0}to{stroke-dashoffset:-1}}
@keyframes homeStepCardFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
@keyframes homeStepBadgePulse{0%,100%{transform:scale(1)}50%{transform:scale(1.04)}}
@keyframes homeStepBadgeOrbit{0%,100%{opacity:.42;transform:rotate(-14deg)}50%{opacity:.82;transform:rotate(16deg)}}
@keyframes homeStepBadgeHalo{0%,100%{opacity:.35;transform:scale(.96)}50%{opacity:.72;transform:scale(1.08)}}
@keyframes homeStepIconFloat{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-2px) scale(1.018)}}
@keyframes homeStepGroundBreathe{0%,100%{opacity:.52;transform:perspective(180px) rotateX(66deg) scaleX(1) scaleY(1)}50%{opacity:.78;transform:perspective(180px) rotateX(66deg) scaleX(1.07) scaleY(1.04)}}
@keyframes homeStepChevronNudge{0%,100%{opacity:.62;transform:translateX(0)}50%{opacity:1;transform:translateX(-3px)}}
@keyframes homeJourneyPathReveal{to{stroke-dashoffset:0}}
@keyframes homeJourneyPathFlow{from{stroke-dashoffset:0}to{stroke-dashoffset:-1}}
@keyframes homeJourneyNodePass{0%,9%,100%{transform:translateZ(0) scale(1)}3.5%{transform:translateZ(0) scale(1.045)}}
@keyframes homeJourneyEndpointOrbit{0%,100%{opacity:.5;transform:rotate(-8deg)}50%{opacity:.86;transform:rotate(24deg)}}
@keyframes homeJourneyEndpointHalo{0%,100%{opacity:.38;transform:scale(.9)}50%{opacity:.78;transform:scale(1.16)}}
@keyframes homeJourneyCloudDrift{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px)}}
@keyframes homeJourneySendDrift{0%,100%{transform:none}50%{transform:translate(2px,-2px) rotate(1deg)}}
@keyframes homeJourneyStarGlow{0%,100%{transform:rotate(0) scale(1)}50%{transform:rotate(6deg) scale(1.08)}}

