.policy-page .policy-hero p{max-width:820px;margin:12px auto 0;color:var(--policy-copy);font-size:14px;line-height:2}
.policy-updated{min-height:40px;margin-top:19px;padding:0 17px;display:inline-flex;align-items:center;justify-content:center;gap:8px;color:#41535e;border:1px solid #e4eeec;border-radius:999px;background:#f2f8f7;font-size:12px;font-style:normal;font-weight:700;box-shadow:0 7px 20px rgba(14,62,56,.04)}
.policy-updated .line-icon{width:17px;height:17px;color:var(--policy-brand);stroke-width:1.8}
.policy-hero-pattern{position:absolute;z-index:0;inset:26px 3% auto;width:94%;height:116px;opacity:.34;background-image:radial-gradient(circle,#a5cec8 1.25px,transparent 1.5px),radial-gradient(circle,#a5cec8 1.25px,transparent 1.5px);background-position:0 0,100% 0;background-size:8px 8px,8px 8px;mask-image:linear-gradient(90deg,#000 0,transparent 22%,transparent 78%,#000 100%);pointer-events:none}
.policy-hero-mark{position:absolute;z-index:1;left:max(7vw,calc(50% - 590px));top:56px;width:138px;height:146px;display:grid;place-items:center;color:#6daea5;border:5px solid currentColor;border-radius:24% 24% 42% 42%;opacity:.1;transform:rotate(45deg);pointer-events:none}
.policy-hero-mark::before{content:"";position:absolute;inset:10px;border:2px solid currentColor;border-radius:22% 22% 40% 40%}
.policy-hero-mark .line-icon{width:62px;height:62px;stroke-width:1.25;transform:rotate(-45deg)}
.policy-page .policy-section{padding:34px 0 68px;background:#fbfcfc}
.policy-page .policy-layout{direction:ltr;display:grid;grid-template-columns:236px minmax(0,1fr);gap:28px;align-items:start;max-width:1120px}
.policy-page[dir="rtl"] :is(.policy-aside,.policy-content){direction:rtl}
.policy-page[dir="ltr"] :is(.policy-aside,.policy-content){direction:ltr}
.policy-aside{position:sticky;top:100px;display:grid;gap:18px}
.policy-page .policy-summary,.policy-help-card{position:static;padding:20px;border:1px solid var(--policy-line);border-radius:14px;background:var(--policy-paper);box-shadow:0 10px 30px rgba(17,37,58,.035)}
.policy-page .policy-summary h2{margin:0 0 12px;color:var(--policy-ink);font-size:16px;font-weight:850}
.policy-page .policy-summary a{position:relative;min-height:34px;padding:6px 0;display:flex;align-items:flex-start;gap:9px;color:#4e5f6c;border:0;font-size:11.5px;font-weight:600;line-height:1.65;text-decoration:none;transition:color .18s ease,transform .18s ease}
.policy-page .policy-summary a span{width:6px;height:6px;flex:0 0 auto;margin-top:6px;border:1.5px solid var(--policy-brand);border-radius:50%;background:#fff}
.policy-page .policy-summary a:hover,.policy-page .policy-summary a:focus-visible{color:var(--policy-brand);transform:translateX(2px);outline:none}
.policy-help-card{text-align:center;padding:22px 17px}
.policy-help-card>span{width:52px;height:52px;margin:0 auto 13px;display:grid;place-items:center;color:var(--policy-ink);border-radius:50%;background:var(--policy-soft)}
.policy-help-card>span .line-icon{width:27px;height:27px;stroke-width:1.6}
.policy-help-card h2{margin:0;color:var(--policy-ink);font-size:16px}
.policy-help-card p{margin:8px 0 15px;color:var(--policy-copy);font-size:11.5px;line-height:1.75}
.policy-help-card .btn{width:100%;min-height:38px;padding-inline:10px;border-color:#8bb9b3;color:#0b6159;background:#fff;font-size:11.5px}
.policy-page .policy-content{display:grid;gap:8px;border:0}
.policy-page .policy-card{min-height:100px;padding:16px 18px;display:grid;grid-template-columns:58px minmax(0,1fr);gap:17px;align-items:start;border:1px solid var(--policy-line);border-radius:12px;background:var(--policy-paper);box-shadow:0 5px 18px rgba(17,37,58,.025);scroll-margin-top:112px;transition:border-color .2s ease,box-shadow .2s ease,transform .2s ease}
.policy-page .policy-card:hover{border-color:#bfd8d4;box-shadow:0 12px 26px rgba(17,84,76,.055);transform:translateY(-1px)}
.policy-card-icon{width:58px;height:58px;display:grid;place-items:center;color:#0c6e65;border-radius:10px;background:linear-gradient(145deg,#f5faf9,#edf6f4)}
.policy-card-icon .line-icon{width:31px;height:31px;stroke-width:1.55}
.policy-page .policy-content h2{margin:1px 0 6px;color:var(--policy-ink);font-size:16px;font-weight:850;line-height:1.55}
.policy-page .policy-content h2 b{font-size:13px;font-weight:850}
.policy-copy{display:grid;gap:7px}
.policy-page .policy-content .policy-copy p{margin:0;color:var(--policy-copy);font-size:12px;line-height:1.9}
.policy-page .policy-contact{margin-top:2px;padding:16px 18px;display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:14px;align-items:center;border:1px solid #d8e8e5;border-radius:12px;background:linear-gradient(90deg,#edf7f5,#f6faf9);box-shadow:none}
.policy-contact-icon{width:42px;height:42px;display:grid;place-items:center;color:var(--policy-brand);border-radius:50%;background:rgba(255,255,255,.78)}
.policy-contact-icon .line-icon{width:23px;height:23px}
.policy-page .policy-contact strong{display:block;color:var(--policy-ink);font-size:13px}
.policy-page .policy-contact p{margin:4px 0 0;color:var(--policy-copy);font-size:11px;line-height:1.65}
.policy-page .policy-contact .btn{min-height:38px;padding-inline:14px;color:#0b6159;border-color:#a4c7c2;background:#fff;font-size:11px}
.public-footer.marketing-footer>.marketing-footer-bottom nav{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:10px 22px}
.public-footer.marketing-footer>.marketing-footer-bottom nav button{min-height:28px;text-underline-offset:4px;transition:color .18s ease,text-decoration-color .18s ease}
.public-footer.marketing-footer>.marketing-footer-bottom nav button:hover,.public-footer.marketing-footer>.marketing-footer-bottom nav button:focus-visible{color:#fff;text-decoration:underline;text-decoration-color:rgba(255,255,255,.7);outline:none}
@media(max-width:940px){
  .policy-page .policy-hero{min-height:255px;padding-top:44px}
  .policy-page .policy-layout{grid-template-columns:1fr;gap:18px}
  .policy-aside{position:static;grid-template-columns:minmax(0,1.45fr) minmax(220px,.55fr);align-items:stretch}
  .policy-page .policy-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:22px;align-content:start}
  .policy-page .policy-summary h2{grid-column:1/-1}
  .policy-hero-mark{left:5vw;top:50px;width:112px;height:120px}
  .public-footer.marketing-footer>.marketing-footer-bottom nav{display:flex!important}
}
@media(max-width:640px){
  .policy-page .policy-hero{min-height:244px;padding:38px 16px 34px}
  .policy-page .policy-hero h1{font-size:31px}
  .policy-page .policy-hero p{font-size:12.5px;line-height:1.85}
  .policy-updated{min-height:36px;margin-top:16px;font-size:11px}
  .policy-hero-mark{left:-22px;top:54px;width:92px;height:100px}
  .policy-page .policy-section{padding:20px 0 42px}
  .policy-aside{grid-template-columns:1fr}
  .policy-page .policy-summary{grid-template-columns:1fr 1fr;padding:17px}
  .policy-page .policy-summary a{font-size:10.5px}
  .policy-help-card{display:none}
  .policy-page .policy-card{min-height:0;padding:14px;grid-template-columns:45px minmax(0,1fr);gap:12px;border-radius:11px}
  .policy-card-icon{width:45px;height:45px}
  .policy-card-icon .line-icon{width:24px;height:24px}
  .policy-page .policy-content h2{font-size:14px}
  .policy-page .policy-content .policy-copy p{font-size:11.5px;line-height:1.8}
  .policy-page .policy-contact{grid-template-columns:38px minmax(0,1fr)}
  .policy-contact-icon{width:38px;height:38px}
  .policy-page .policy-contact .btn{grid-column:1/-1;width:100%}
  .public-footer.marketing-footer>.marketing-footer-bottom{gap:10px;flex-direction:column;text-align:center}
  .public-footer.marketing-footer>.marketing-footer-bottom nav{gap:6px 14px}
}
@media(prefers-reduced-motion:reduce){.policy-page .policy-card,.policy-page .policy-summary a{transition:none}}

